#include <os/list.h>
#include <os/mm.h>
#include <os/lock.h>
#include <os/sched.h>
#include <os/time.h>
#include <os/irq.h>
#include <os/binsem.h>
#include <os/smp.h>
#include <screen.h>
#include <stdio.h>
#include <assert.h>
#include <csr.h>
#include <user_programs.h>
#include <os/elf.h>

extern void __global_pointer$();

pcb_t pcb[NUM_MAX_TASK];
pcb_t kernel_pcb[NR_CPUS];
const pcb_t *core0_tp = &kernel_pcb[0];
const pcb_t *core1_tp = &kernel_pcb[1];
const ptr_t kernel_stack_0 = INIT_KERNEL_STACK + PAGE_SIZE;
const ptr_t kernel_stack_1 = INIT_KERNEL_STACK + 2 * PAGE_SIZE;

LIST_HEAD(ready_queue);
LIST_HEAD(sleep_queue);

/* current running task PCB */
pcb_t * volatile current_running[NR_CPUS];
pcb_t * volatile current_cpu_running;

/* global process id */
pid_t process_id = 2;

/* at most this many arguments are handed over to a new process */
#define MAX_EXEC_ARGC 16

/*
 * A brand new address space costs a few frames right away (the ELF image, the
 * first stack page and the kernel stack).  Refuse to exec instead of running
 * into an allocation that cannot be satisfied even by swapping.
 */
#define EXEC_MIN_FREE_PAGES 16

static void reclaim_pcb(pcb_t *task);

/*
 * Only modify PCB, current_running, process_id and ready_queue
 * DO NOT STORE OR RESTORE
 * trick: modify $tp in ret_from_exception to ensure
 * disable_preempt() and enable_preempt() modify the same PCB
 */
void scheduler(void)
{
    pcb_t *prev = current_running[cpu_id];
    pcb_t *next;
    pcb_t *dying = NULL;
    list_node_t *next_node;

    if (prev != &kernel_pcb[cpu_id]) {
        if (prev->status == TASK_RUNNING) {
            /* still runnable: back to the tail of the ready queue */
            prev->status = TASK_READY;
            prev->ready_tick = get_ticks();
            list_add_tail(&prev->list, &ready_queue);
        } else if (prev->status == TASK_KILLED) {
            /* it died on this core; its address space can only be torn down
             * once `satp` no longer points at it, so remember it for now */
            list_del(&prev->list);
            dying = prev;
        }
    }

    next_node = max_priority_node();
    if (next_node == NULL) {
        /* nothing this hart may run, go back to its idle task */
        next = &kernel_pcb[cpu_id];
    } else {
        list_del(next_node);
        next = list_entry(next_node, pcb_t, list);
    }

    next->status = TASK_RUNNING;
    next->cpu_id = cpu_id;
    current_running[cpu_id] = next;
    /* ret_from_exception restores the context of `current_cpu_running` */
    current_cpu_running = next;

    /* every task owns its own cursor position */
    screen_cursor_x[cpu_id] = next->cursor_x;
    screen_cursor_y[cpu_id] = next->cursor_y;

    /* install the address space of the new task; the kernel window is part
     * of every page table, so the code below keeps running just fine */
    set_satp(SATP_MODE_SV39, 0, ((uintptr_t)next->pgdir) >> NORMAL_PAGE_SHIFT);
    local_flush_tlb_all();

    if (dying != NULL) {
        free_process_user_page(dying->pgdir);
        dying->pgdir = (PTE*)PGDIR_PA;
        reclaim_pcb(dying);
    }
}

/*
 * Prepare the kernel stack of a brand new process so that ret_from_exception
 * drops it into `entry_point` in user mode with argc/argv in a0/a1.
 */
static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point,
                           pcb_t *new_pcb, int argc, uintptr_t argv)
{
    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
    new_pcb->kernel_sp = kernel_stack - sizeof(regs_context_t);

    /* the pcb slot may have been used before, do not inherit stale registers */
    memset(pt_regs, 0, sizeof(regs_context_t));

    /* initialization registers: ra, sp, gp, a0, a1, sstatus, sepc, sscratch */
    pt_regs->regs[1] = (reg_t)entry_point;       //ra
    pt_regs->regs[2] = (reg_t)user_stack;        //sp
    pt_regs->regs[3] = (reg_t)__global_pointer$; //gp
    pt_regs->regs[10] = (reg_t)argc;             //a0, argc of main()
    pt_regs->regs[11] = (reg_t)argv;             //a1, argv of main()
    pt_regs->sepc = (reg_t)entry_point;          //sepc
    pt_regs->sstatus = (reg_t)SR_SPIE;           //SPP = 0, SPIE = 1
    pt_regs->sscratch = (reg_t)new_pcb;          //sscratch = tp
}

/*
 * Copy the arguments of the caller onto the freshly created user stack of
 * `new_pcb` and return the user virtual address of the argv array.  The page
 * is filled in through the kernel's direct mapping, which is reachable no
 * matter which address space is currently installed.
 */
static uintptr_t init_user_stack(pcb_t *new_pcb, int argc, char *argv[])
{
    uintptr_t top_va = USER_STACK_ADDR;
    uintptr_t top_kva = alloc_page_helper(top_va - PAGE_SIZE,
                                          (uintptr_t)new_pcb->pgdir) + PAGE_SIZE;
    /* the last `top_va - va` bytes of the page hold the address `va` */
    #define STACK_KVA(va) (top_kva - (top_va - (uintptr_t)(va)))

    uintptr_t string_va[MAX_EXEC_ARGC];
    uintptr_t sp = top_va;
    int i;

    if (argc < 0 || argv == NULL) {
        argc = 0;
    }
    if (argc > MAX_EXEC_ARGC) {
        argc = MAX_EXEC_ARGC;
    }

    /* the strings themselves, topmost first */
    for (i = argc - 1; i >= 0; i--) {
        int len = strlen(argv[i]) + 1;
        sp -= len;
        memcpy((uint8_t *)STACK_KVA(sp), (const uint8_t *)argv[i], (uint32_t)len);
        string_va[i] = sp;
    }

    /* then the NULL terminated array pointing at them */
    sp = ROUNDDOWN(sp, sizeof(uintptr_t));
    sp -= (argc + 1) * sizeof(uintptr_t);
    uintptr_t *slot = (uintptr_t *)STACK_KVA(sp);
    for (i = 0; i < argc; i++) {
        slot[i] = string_va[i];
    }
    slot[argc] = 0;

    uintptr_t argv_va = sp;
    /* the RISC-V ABI wants a 16 byte aligned stack pointer */
    new_pcb->user_sp = ROUNDDOWN(sp, 16);

    #undef STACK_KVA
    return argv_va;
}

/*
 * Load the ELF image called `file_name` into a brand new address space and
 * make it a runnable process.  The return value is the one the shell expects:
 * -1 when there is no such program, 0 when the process table is full, -2 when
 * memory ran out and the new pid on success.
 */
pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
{
    disable_preempt();
    /* file_name and argv live in the caller's user space */
    enable_sum();

    unsigned char *binary = NULL;
    int length = 0;
    if (file_name == NULL || !get_elf_file(file_name, &binary, &length)) {
        disable_sum();
        enable_preempt();
        return -1;
    }

    /* look for a free pcb: `pid == -1` marks an unused slot */
    int i;
    for (i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == -1) {
            break;
        }
    }
    if (i == NUM_MAX_TASK) {
        disable_sum();
        enable_preempt();
        return 0;
    }

    if (free_page_num() < EXEC_MIN_FREE_PAGES) {
        disable_sum();
        enable_preempt();
        return -2;
    }

    pcb_t *new_pcb = &pcb[i];
    new_pcb->pgdir = init_page_table();
    /* the kernel stack is a pinned physical page used through the direct map */
    new_pcb->kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
    new_pcb->kernel_stack_base = new_pcb->kernel_sp;
    new_pcb->user_sp = USER_STACK_ADDR;
    new_pcb->user_stack_base = USER_STACK_ADDR;
    new_pcb->preempt_count = 0;
    init_list_head(&new_pcb->wait_list);
    init_list_head(&new_pcb->timer.list);
    new_pcb->binsem_num = 0;
    new_pcb->pid = process_id++;
    new_pcb->type = USER_PROCESS;
    new_pcb->status = TASK_READY;
    new_pcb->mode = mode;
    new_pcb->priority = 1;
    new_pcb->ready_tick = get_ticks();
    /* a child may run wherever its parent was allowed to run */
    new_pcb->mask = current_running[cpu_id]->mask;
    if (new_pcb->mask == 0) {
        new_pcb->mask = (1UL << NR_CPUS) - 1;
    }
    new_pcb->cpu_id = cpu_id;
    new_pcb->cursor_x = 1;
    new_pcb->cursor_y = 1;

    uintptr_t entry = load_elf(binary, (unsigned)length,
                               (uintptr_t)new_pcb->pgdir, alloc_page_helper);
    uintptr_t argv_va = init_user_stack(new_pcb, argc, argv);

    init_pcb_stack(new_pcb->kernel_sp, new_pcb->user_sp, entry,
                   new_pcb, argc, argv_va);
    list_add_tail(&new_pcb->list, &ready_queue);

    pid_t new_pid = new_pcb->pid;
    disable_sum();
    enable_preempt();
    return new_pid;
}

/* Give up every binary semaphore `task` still holds and hand each of them to
 * the next waiter, so that nobody stays blocked on a dead process. */
static void release_binsem(pcb_t *task)
{
    while (task->binsem_num > 0) {
        int id = task->binsem_id[--task->binsem_num];
        binsem_node_t *node = &binsem_nodes[id];

        node->sem++;
        if (node->sem <= 0 && !list_empty(&node->block_queue)) {
            list_node_t *heir_node = node->block_queue.next;
            pcb_t *heir = list_entry(heir_node, pcb_t, list);
            heir->binsem_id[heir->binsem_num++] = id;
            do_unblock(heir_node);
        }
    }
}

/* Common part of exiting and being killed: hand back the semaphores, wake
 * everybody who waits for this task and disarm its sleep timer. */
static void release_resources(pcb_t *task)
{
    release_binsem(task);

    while (!list_empty(&task->wait_list)) {
        do_unblock(task->wait_list.next);
    }

    /* a sleeping task may still have an armed timer */
    list_del(&task->timer.list);
}

/*
 * Finish the teardown of a task whose address space is already gone.  The
 * kernel stack is still in use at this point, so it is released later: either
 * by the parent in do_waitpid() or by the idle task of core 0.
 */
static void reclaim_pcb(pcb_t *task)
{
    list_del(&task->list);

    if (task->mode == ENTER_ZOMBIE_ON_EXIT) {
        /* the parent reaps us in do_waitpid() */
        task->status = TASK_ZOMBIE;
    } else {
        task->status = TASK_EXITED;
        list_add_tail(&task->list, &kernel_pcb[0].wait_list);
    }
}

void do_exit()
{
    disable_preempt();
    pcb_t *cur = current_running[cpu_id];

    /* take ourselves out of the ready queue first: the wakeups below may
     * reschedule, which must not put a dying task back */
    list_del(&cur->list);
    release_resources(cur);

    /* We are still running on this address space, so scheduler() performs the
     * teardown for us right after it has installed the next one. */
    cur->status = TASK_KILLED;
    scheduler();

    enable_preempt();
}

// sleep(seconds)
void do_sleep(uint32_t sleep_time)
{
    // 1. block the current_running
    // 2. create a timer which calls `do_unblock` when timeout
    // 3. reschedule because the current_running is blocked
    do_block(&current_running[cpu_id]->list, &sleep_queue);
    list_node_t* parameter = &current_running[cpu_id]->list;
    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
    scheduler();
}

int do_kill(pid_t pid)
{
    disable_preempt();

    pcb_t *victim = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            victim = &pcb[i];
            break;
        }
    }
    if (victim == NULL || victim->status == TASK_EXITED ||
        victim->status == TASK_ZOMBIE || victim->status == TASK_KILLED) {
        enable_preempt();
        return 0;
    }

    if (victim == current_running[cpu_id]) {
        /* killing ourselves is just an exit */
        enable_preempt();
        do_exit();
        return 1;
    }

    release_resources(victim);

    if (victim->status == TASK_RUNNING) {
        /* it is running on the other hart, and its page table is live there:
         * flag it and let that hart finish the teardown when it reschedules */
        victim->status = TASK_KILLED;
    } else {
        free_process_user_page(victim->pgdir);
        victim->pgdir = (PTE*)PGDIR_PA;
        reclaim_pcb(victim);
    }

    enable_preempt();
    return 1;
}

/*
 * A blocked process can only be resumed in user mode, so waitpid cannot
 * simply continue where it left off.  Instead the caller is blocked on the
 * child's wait list and `sepc` is rewound onto the `ecall`, so once the child
 * exits the system call is executed again -- this time finding the child
 * gone (or a zombie ready to be reaped).  The return value has to be `pid`
 * in that case because handle_syscall() writes it back into a0, which is the
 * very argument the retried `ecall` will pick up.
 */
int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    disable_preempt();

    pcb_t *child = NULL;
    for (int i = 0; i < NUM_MAX_TASK; i++) {
        if (pcb[i].pid == pid) {
            child = &pcb[i];
            break;
        }
    }

    if (child == NULL) {
        /* already gone and cleaned up */
        enable_preempt();
        return 0;
    }

    if (child->status == TASK_ZOMBIE || child->status == TASK_EXITED) {
        /* reap it: release the kernel stack and free the pcb slot */
        free_user_page(kva2pa(child->kernel_stack_base - PAGE_SIZE));
        list_del(&child->list);
        child->status = TASK_EXITED;
        child->pid = -1;
        enable_preempt();
        return 1;
    }

    /* still alive: sleep on it and retry the system call when woken up */
    regs->sepc = regs->sepc - 4;
    do_block(&current_running[cpu_id]->list, &child->wait_list);
    scheduler();

    enable_preempt();
    return pid;
}

void do_process_show(char* buffer)
{
    enable_sum();
    buffer[0] = '\0';
    strcat(buffer, "[PROCESS TABLE]\n");
    strcat(buffer, "INIT 0    STATUS: ");
    if(kernel_pcb[0].status == TASK_BLOCKED){
        strcat(buffer, "BLOCKED    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[0].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[0].status == TASK_RUNNING){
        strcat(buffer, "RUNNING    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[0].mask);
        strcat(buffer, mask);
        strcat(buffer, "    CORE: ");
        char cpu_id[2];
        itoa(cpu_id, kernel_pcb[0].cpu_id);
        strcat(buffer, cpu_id);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[0].status == TASK_READY){
        strcat(buffer, "READY    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[0].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[0].status == TASK_EXITED){
        strcat(buffer, "EXITED    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[0].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[0].status == TASK_ZOMBIE){
        strcat(buffer, "ZOMBIE    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[0].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }

    strcat(buffer, "INIT 1    STATUS: ");
    if(kernel_pcb[1].status == TASK_BLOCKED){
        strcat(buffer, "BLOCKED\n");
    }
    else if(kernel_pcb[1].status == TASK_RUNNING){
        strcat(buffer, "RUNNING    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[1].mask);
        strcat(buffer, mask);
        strcat(buffer, "    CORE: ");
        char cpu_id[2];
        itoa(cpu_id, kernel_pcb[1].cpu_id);
        strcat(buffer, cpu_id);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[1].status == TASK_READY){
        strcat(buffer, "READY    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[1].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[1].status == TASK_EXITED){
        strcat(buffer, "EXITED    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[1].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }
    else if(kernel_pcb[1].status == TASK_ZOMBIE){
        strcat(buffer, "ZOMBIE    MASK: ");
        char mask[2];
        itoa(mask, kernel_pcb[1].mask);
        strcat(buffer, mask);
        strcat(buffer, "\n");
    }

    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid != -1){
            strcat(buffer, "PID: ");
            char pid[10];
            itoa(pid, pcb[i].pid);
            strcat(buffer, pid);
            strcat(buffer, "    STATUS: ");
            if(pcb[i].status == TASK_BLOCKED){
                strcat(buffer, "BLOCKED    MASK: ");
                char mask[2];
                itoa(mask, pcb[i].mask);
                strcat(buffer, mask);
                strcat(buffer, "\n");
            }
            else if(pcb[i].status == TASK_RUNNING){
                strcat(buffer, "RUNNING    MASK: ");
                char mask[2];
                itoa(mask, pcb[i].mask);
                strcat(buffer, mask);
                strcat(buffer, "    CORE: ");
                char cpu_id[2];
                itoa(cpu_id, pcb[i].cpu_id);
                strcat(buffer, cpu_id);
                strcat(buffer, "\n");
            }
            else if(pcb[i].status == TASK_READY){
                strcat(buffer, "READY    MASK: ");
                char mask[2];
                itoa(mask, pcb[i].mask);
                strcat(buffer, mask);
                strcat(buffer, "\n");
            }
            else if(pcb[i].status == TASK_EXITED){
                strcat(buffer, "EXITED    MASK: ");
                char mask[2];
                itoa(mask, pcb[i].mask);
                strcat(buffer, mask);
                strcat(buffer, "\n");
            }
            else if(pcb[i].status == TASK_ZOMBIE){
                strcat(buffer, "ZOMBIE    MASK: ");
                char mask[2];
                itoa(mask, pcb[i].mask);
                strcat(buffer, mask);
                strcat(buffer, "\n");
            }
        }
    }
    disable_sum();
}

pid_t do_getpid()
{
    return current_running[cpu_id]->pid;
}

int do_taskset(pid_t pid, unsigned long mask)
{
    // search the pcb
    pcb_t *set_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            set_pcb = &pcb[i];
            break;
        }
    }
    if(set_pcb == NULL){
        return 0;
    }

    set_pcb->mask = mask;
    return 1;
}

void do_show_exec(char* buffer)
{
    enable_sum();
    buffer[0] = '\0';
    for(int i = 0; i < ELF_FILE_NUM; i++){
        strcat(buffer, elf_files[i].file_name);
        strcat(buffer, "    ");
    }
    strcat(buffer, "\n");
    disable_sum();
}
// block the pcb task into the block queue
void do_block(list_node_t *pcb_node, list_head *queue)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
}

// unblock the `pcb` from the block queue
void do_unblock(list_node_t *pcb_node)
{
    list_del(pcb_node);
    list_add_tail(pcb_node, &ready_queue);
    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
}

/*
 * Pick the ready task with the highest effective priority that is allowed to
 * run on this hart.  The effective priority is the static priority plus an
 * ageing bonus of one point per scheduling tick already spent waiting, so a
 * low priority task cannot starve.  Ties go to the task that has been in the
 * queue longest, which keeps equal priorities round-robin.
 */
list_node_t* max_priority_node(void)
{
    list_node_t *node;
    list_node_t *max_node = NULL;
    uint64_t max_priority = 0;
    uint64_t current_tick = get_ticks();

    for (node = ready_queue.next; node != &ready_queue; node = node->next) {
        pcb_t *task = list_entry(node, pcb_t, list);
        uint64_t waited_tick = 0;
        uint64_t priority;

        /* cpu affinity */
        if (!(task->mask & (1UL << cpu_id))) {
            continue;
        }

        if (current_tick > task->ready_tick) {
            waited_tick = current_tick - task->ready_tick;
        }
        priority = (uint64_t)task->priority;
        if (timer_interval != 0) {
            priority += waited_tick / timer_interval;
        }

        if (max_node == NULL || priority > max_priority) {
            max_node = node;
            max_priority = priority;
        }
    }

    return max_node;
}

